let hub = null;

function activate(context) {
  hub = new Hub(context);
  // exposed for test\integration (vscode.extensions.getExtension(...).exports)
  return { hub };
}

function deactivate() {
  const h = hub;
  hub = null;
  // (1010 review of leaks #2: the window reloaded / closed while this extension's own build ran -- the OS killed powershell /
  //  cmake / ld with the extension host, mid-link, and nothing removed the cut exe. Stopped as ⏹ does (taskkill /T, then the
  //  cut exe removed), waited for a moment; the compiler's syntax check too. F5's build is VS Code's task: not touched)
  const waits = [];
  try {
    const rb = h && h.runBar, b = rb && rb.building;
    if (b && b.run && !b.run.cancelled && !b.run.closed && rb.cancelBuild()) waits.push(new Promise(r => setTimeout(r, 4000)));
  } catch (e) { /* closing */ }
  try { const cc = h && h.cppChecks; if (cc && cc.syntax) { cc.killTree(cc.syntax); cc.syntax = null; } } catch (e) { /* closing */ }
  return waits.length ? Promise.all(waits) : undefined;
}

