/** 1009 performance review #4: lex.analyze of a document, once per version (the lenses asked it twice on every pause: ~0.1 s a time on csystem.cpp) */
const AN_CACHE = new Map();
function analyzeDoc(doc, text) {
  const k = doc && doc.uri ? doc.uri.toString() : '';
  const c = k ? AN_CACHE.get(k) : null;
  if (c && c.version === doc.version && c.len === text.length) return c.an;
  const an = lex.analyze(text);
  if (k) { AN_CACHE.delete(k); AN_CACHE.set(k, { version: doc.version, len: text.length, an }); while (AN_CACHE.size > 8) AN_CACHE.delete(AN_CACHE.keys().next().value); }
  return an;
}
/**
 * 1009 second review (debug #1 / #2): each debug session's own stopped / running, from its adapter's messages (stopped;
 * continued, a continue / step answered) -- VS Code keeps a THREAD focused after 繼續, which read as "paused" while the
 * machine program ran (⏹ then skipped its normal close). session id -> { session, stopped, threadId }
 */
const DBG_RUN = new Map();
/**
 * EastSun 1009「你是不是搜尋文字又開了一個新檔案 但是上面已經有開過一樣的檔案了」: the group where `uri` already has a tab
 * (the active group first; never the run strip's) -- a search result / a jump opened a SECOND tab of the same file in the
 * group the user came from. -> its viewColumn, else `fallback`
 */
/** two uris of the same file (scheme the same, the path compared as Windows does) */
function sameUri(a, b) {
  if (!a || !b) return false;
  if (a.scheme !== b.scheme) return false;
  return a.scheme === 'file' || a.fsPath ? web.samePath(a.fsPath, b.fsPath) : a.toString() === b.toString();
}
function openColumnOf(uri, fallback) {
  try {
    const key = uri.toString().toLowerCase();
    const fp = uri.scheme === 'file' ? path.resolve(uri.fsPath).toLowerCase() : null;
    const same = t => t && t.input && t.input.uri && (t.input.uri.toString().toLowerCase() === key || (fp && t.input.uri.scheme === 'file' && path.resolve(t.input.uri.fsPath).toLowerCase() === fp));
    const tg = vscode.window.tabGroups;
    if (!tg) return fallback;
    const gs = (tg.all || []).filter(g => !(typeof RunStrip !== 'undefined' && RunStrip.isStripGroup(g)));
    const act = tg.activeTabGroup;
    if (act && gs.includes(act) && act.tabs.some(same)) return act.viewColumn;
    const g = gs.find(x => x.tabs.some(same));
    return g && g.viewColumn ? g.viewColumn : fallback;
  } catch (e) { return fallback; }
}
/**
 * 1009 review (windows #1): the wb_* programs each VS Code window started under its debugger -- %TEMP%\ht9045_owned_pids.json
 * { pid: { host (that window's extension host), path, at } }. ⏹ / F5 of another window used to close (and after 30 s
 * force-kill) them, even one stopped at a breakpoint there. A program another living window owns is left alone.
 */
const OWNED_FILE = path.join(require('os').tmpdir(), 'ht9045_owned_pids.json');
function ownedRead() { try { return JSON.parse(fs.readFileSync(OWNED_FILE, 'utf8')) || {}; } catch (e) { return {}; } }
function ownedAdd(pid, prog) {
  if (!(pid > 0)) return;
  try {
    const o = ownedRead();
    o[String(pid)] = { host: process.pid, path: prog ? String(prog).toLowerCase() : '', at: Date.now() };
    for (const k of Object.keys(o)) if (Date.now() - Number(o[k].at || 0) > 7 * 86400000) delete o[k];
    const tmp = OWNED_FILE + '.' + process.pid + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(o));
    fs.renameSync(tmp, OWNED_FILE);
  } catch (e) { /* not recorded: treated as before */ }
}
/** the program (pid, its exe path) belongs to ANOTHER window that is still open */
function ownedByOther(p, owned) {
  const e = (owned || ownedRead())[String(p && p.pid)];
  if (!e || e.host === process.pid) return false;
  // (the pid used again by another program -- compared by real path: a junction / slashes made the same exe two names)
  const rp = x => { try { return fs.realpathSync(String(x)).toLowerCase(); } catch (er) { return path.resolve(String(x)).toLowerCase(); } };
  if (e.path && p.path && rp(e.path) !== rp(p.path)) return false;
  try { process.kill(Number(e.host), 0); return true; } catch (x) { return !!(x && x.code === 'EPERM'); }
}
/** 1009 review (keys #5): BCB's keys on -- the USER level of the setting, the one keybindings.json is written from; the
 *  labels (run strip, title bar, status bar) say the keys of the same level */
function bcbKeysOn() {
  const c = vscode.workspace.getConfiguration('ht9045Designer');
  const i = c.inspect ? c.inspect('bcbDebugKeys') : null;
  return i ? i.globalValue !== false : c.get('bcbDebugKeys') !== false;
}
const RUNKEYS = on => (on ? { go: 'F9', stop: 'Ctrl+F2', over: 'F8', into: 'F7', out: 'Shift+F8' } : { go: 'F5', stop: 'Shift+F5', over: 'F10', into: 'F11', out: 'Shift+F11' });
function bpMovedKey(uri, line) { return String(uri).toLowerCase() + '#' + line; }
function markBpMoved(bps) { for (const b of bps || []) if (b && b.location && b.location.uri) BP_MOVED.add(bpMovedKey(b.location.uri.toString(), b.location.range ? b.location.range.start.line : -1)); }

