    //  a component and its handler goes into that class. opts.cls (tests): '' = none, 'TfX' = that one; opts.cppTarget
    // (a folder given (tests): never the real tree's forms\ -- opts.formsDir, or no class)
    const formsDir = opts.formsDir || (opts.dir ? null : this.portTree() ? path.join(this.portTree(), 'forms') : null);
    let cls = opts.cls;
