    { const why = obj ? this.fileNameWhy(obj + '.h', true) : ''; if (why) { vscode.window.showWarningMessage(cls + '：' + why + '。'); return null; } }
    if (cls && (!formsDir || fs.existsSync(path.join(formsDir, obj + '.h')) || fs.existsSync(path.join(formsDir, obj + '.cpp')))) { vscode.window.showWarningMessage(formsDir ? 'forms\\' + obj + '.h／.cpp 已經有了，沒有建頁面。' : '找不到 C++ 移植樹的 forms 資料夾。'); return null; }
    // (1008 audit F6: a class of that name already somewhere in the tree -- another TfX would not link)
