/**
 * WPF / WinForms Toolbox: "Pointer" is the first item -- a click on it puts the picked-up tool
 * back (the surface is for selecting again), and the toolbox goes back to it after a tool is put down.
 */
const POINTER = { cls: '@pointer', label: '指標', note: '回到選取（放下拿起的工具）', icon: 'inspect' };

/** WPF: the caret inside a handler's body (the first statement, or just after an empty body's brace), or null. */
function bodyPos(doc, line0) {
  const b = cppstub.bodyStart(doc.getText(), line0);
  return b ? new vscode.Position(b.line, b.col) : null;
}

/** 工具箱 (WPF Toolbox): the component classes a page can get; a click adds one. */
const TPL_GROUP = '我的範本';
class ToolboxTree {
  // 0.153 (the WPF gap list G2): Pointer, then the categories (常用 / 容器 / IO 元件 / 其他), the components in them
  // (1006, C++Builder Component > Create Component Template: + 我的範本, the user's own groups of components)
  constructor(hub) {
    this.hub = hub;
    this.groups = new Map(toolbox.CATS.map(c => [c, { group: c }]));
    this.tplGroup = { group: TPL_GROUP, tpl: true };
    this._em = new vscode.EventEmitter();
    this.onDidChangeTreeData = this._em.event;
  }
  refresh() { this._em.fire(); }
  templates() { return this.hub && this.hub.templates ? this.hub.templates() : []; }
  getChildren(n) {
    if (!n) return [POINTER, ...toolbox.CATS.filter(c => toolbox.ITEMS.some(i => toolbox.catOf(i) === c)).map(c => this.groups.get(c))].concat(this.templates().length ? [this.tplGroup] : []);
    if (n.tpl) return this.templates().map(t => ({ template: t }));
    if (n.group) return toolbox.ITEMS.filter(i => toolbox.catOf(i) === n.group);
    return [];
  }
  // (reveal -- back to Pointer -- asks for the parent: Pointer and the categories are at the top)
  getParent(it) { return !it || it === POINTER || it.group ? null : it.template ? this.tplGroup : this.groups.get(toolbox.catOf(it)) || null; }
  getTreeItem(it) {
    if (it && it.tpl) {
      const g = new vscode.TreeItem(TPL_GROUP, vscode.TreeItemCollapsibleState.Expanded);
      g.id = 'toolcat:@templates';
      g.description = this.templates().length + ' 個';
      g.tooltip = '你存的元件範本（C++Builder 的 Component Template）：選好一組元件 → 右鍵「存成工具箱範本…」。\n點一個範本＝放進選取的容器（或選取元件的下面），名稱自動改成新的。';
      g.contextValue = 'toolCat';
      return g;
    }
    if (it && it.template) {
      const t = it.template;
      const ti = new vscode.TreeItem(t.name, vscode.TreeItemCollapsibleState.None);
      ti.id = 'tooltpl:' + t.name;
      ti.description = t.ids.length + ' 個元件　' + t.ids.slice(0, 3).join('、') + (t.ids.length > 3 ? '…' : '');
      ti.tooltip = '範本「' + t.name + '」：' + t.ids.join('、') + (t.from ? '\n（從 ' + t.from + ' 存的）' : '') + '\n\n點一下＝放進選取的容器（或選取元件的下面）；右鍵＝刪除這個範本';
      ti.iconPath = new vscode.ThemeIcon('symbol-snippet');
      ti.command = { command: 'ht9045Designer.templateInsert', title: '放置範本', arguments: [t.name] };
      ti.contextValue = 'toolTemplate';
      return ti;
    }
    if (it && it.group) {
      const g = new vscode.TreeItem(it.group, vscode.TreeItemCollapsibleState.Expanded);
      g.id = 'toolcat:' + it.group;
      g.description = toolbox.ITEMS.filter(i => toolbox.catOf(i) === it.group).length + ' 個';
      g.contextValue = 'toolCat';
      return g;
    }
    if (it === POINTER) {
      const p = new vscode.TreeItem(it.label, vscode.TreeItemCollapsibleState.None);
      p.id = 'tool:@pointer';
      p.description = it.note;
      p.tooltip = '指標（WPF 工具箱的 Pointer）：放下拿起的工具，設計畫面回到選取（同 Esc）。\n放好一個元件後工具箱也會回到這一項。';
      p.iconPath = new vscode.ThemeIcon(it.icon);
      p.command = { command: 'ht9045Designer.toolboxArm', title: '指標', arguments: [it.cls] };
      p.contextValue = 'toolPointer';
      return p;
    }
    const item = new vscode.TreeItem(it.label, vscode.TreeItemCollapsibleState.None);
    item.id = 'tool:' + it.cls;
    item.description = it.note + '　' + it.cls;
    item.tooltip = it.cls + '：' + it.note + '（名稱 ' + it.base + '1、' + it.base + '2…）\n\n' +
      '點一下＝拿起這個工具：到設計畫面上點一下放在那裡，或拖一個框（連大小）；Esc 取消\n' +
      '連點兩下＝直接新增：選了 Panel／GroupBox／分頁／表單 → 放進去（左上 8,8）；選了其他元件 → 放在它下面\n\n寫進 HTML 原始碼，Ctrl+Z 復原。';
    item.iconPath = new vscode.ThemeIcon(it.icon);
    item.command = { command: 'ht9045Designer.toolboxArm', title: '放置', arguments: [it.cls] };
    item.contextValue = 'tool';
    return item;
  }
}

/**
 * (1008, feature gap #14): 工具箱 floated (Visual Studio's floating Toolbox) -- a webview window (media/toolboxwin.*)
 * showing the side view's rows (Hub.toolboxRows: the tree's own items). What it sends goes to the side view's handlers:
 *   { type: 'click', cmd, arg, shift } -- the row's own command: toolboxArm (pick up; two quick clicks = added) or
 *     templateInsert; Shift on a tool = toolboxArmSticky (the side view's right-click 連續放置)
 *   { type: 'add', cmd, arg } -- Enter: added at once (the side view's Enter, toolboxAddNow) / the template put in
 * The hub tells it which tool is in the hand ({ type: 'sel', cls }) and when 我的範本 changes (rows again).
 */
class ToolboxWindow {
  static show(hub) {
    if (hub.toolboxWin && !hub.toolboxWin.disposed) { hub.toolboxWin.panel.reveal(undefined, false); hub.toolboxWin.refresh(); return hub.toolboxWin; }
    hub.toolboxWin = new ToolboxWindow(hub);
    return hub.toolboxWin;
  }

  constructor(hub) {
    this.hub = hub;
    this.disposed = false;
    const media = vscode.Uri.joinPath(hub.ctx.extensionUri, 'media');
    this.panel = vscode.window.createWebviewPanel('ht9045Designer.toolboxWindow', '工具箱', { viewColumn: vscode.ViewColumn.Beside, preserveFocus: false },
      { enableScripts: true, enableCommandUris: false, localResourceRoots: [media], retainContextWhenHidden: true });
    const w = this.panel.webview;
    const nonce = crypto.randomBytes(16).toString('base64');
    w.html = '<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="UTF-8">' +
      '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src ' + w.cspSource + '; script-src \'nonce-' + nonce + '\';">' +
      '<link rel="stylesheet" href="' + w.asWebviewUri(vscode.Uri.joinPath(media, 'toolboxwin.css')) + '"></head><body>' +
      '<script nonce="' + nonce + '" src="' + w.asWebviewUri(vscode.Uri.joinPath(media, 'toolboxwin.js')) + '"></script></body></html>';
    w.onDidReceiveMessage(m => this.onMessage(m));
    this.panel.onDidDispose(() => { this.disposed = true; if (hub.toolboxWin === this) hub.toolboxWin = null; });
    // (its own window, floating -- VS Code 1.86+; older ones keep it as a tab beside, which can be dragged out)
    Promise.resolve(vscode.commands.executeCommand('workbench.action.moveEditorToNewWindow')).catch(() => { /* stays a tab */ });
  }

  post(m) { if (!this.disposed) { try { Promise.resolve(this.panel.webview.postMessage(m)).catch(() => {}); } catch (e) { /* closed */ } } }
  refresh() {
    const d = this.hub.active;
    this.post({ type: 'rows', rows: this.hub.toolboxRows(), sel: (d && d.armed) || POINTER.cls });
  }
  select(cls) { this.post({ type: 'sel', cls: cls || POINTER.cls }); }

  /** A message from the window -> the side view's own handlers (the result, for the tests). */
  async onMessage(m) {
    if (!m || typeof m !== 'object') return null;
    try {
      if (m.type === 'ready') { this.refresh(); return null; }
      const arg = typeof m.arg === 'string' ? m.arg : null;
      if (m.type === 'click') {
        if (m.cmd === 'ht9045Designer.toolboxArm') return m.shift && arg !== POINTER.cls ? this.hub.toolboxArmSticky(arg) : await this.hub.toolboxArm(arg);
        if (m.cmd === 'ht9045Designer.templateInsert') return await this.hub.cmdTemplateInsert(arg);
        return null;
      }
      if (m.type === 'add') {
        if (m.cmd === 'ht9045Designer.toolboxArm') return await this.hub.toolboxAddNow(arg);
        if (m.cmd === 'ht9045Designer.templateInsert') return await this.hub.cmdTemplateInsert(arg);
      }
    } catch (e) { this.hub.log('浮動工具箱：' + (e && e.stack || e)); }
    return null;
  }
}

// ---------------------------------------------------------------------------
/** 接線總覽 tab (one per designer; re-running the command refreshes it). */
class OverviewPanel {
  static show(hub, d, data) {
    if (d.overview && !d.overview.disposed) { d.overview.set(data); d.overview.panel.reveal(undefined, true); return d.overview; }
    d.overview = new OverviewPanel(hub, d, data);
    return d.overview;
  }

  constructor(hub, d, data) {
    this.hub = hub;
    this.d = d;
    this.data = data;
    this.disposed = false;
    const media = vscode.Uri.joinPath(hub.ctx.extensionUri, 'media');
    this.panel = vscode.window.createWebviewPanel('ht9045Designer.overview', '接線總覽：' + path.basename(d.file),
      { viewColumn: vscode.ViewColumn.Beside, preserveFocus: true },
      { enableScripts: true, enableCommandUris: false, localResourceRoots: [media], retainContextWhenHidden: true });
    const w = this.panel.webview;
    const nonce = crypto.randomBytes(16).toString('base64');
    w.html = '<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="UTF-8">' +
      '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src ' + w.cspSource + '; script-src \'nonce-' + nonce + '\';">' +
      '<link rel="stylesheet" href="' + w.asWebviewUri(vscode.Uri.joinPath(media, 'overview.css')) + '"></head><body><div id="root"></div>' +
      '<script nonce="' + nonce + '" src="' + w.asWebviewUri(vscode.Uri.joinPath(media, 'overview.js')) + '"></script></body></html>';
    w.onDidReceiveMessage(m => this.onMessage(m));
    // (1010 operate walkthrough #3: made again 1.5 s after a page / .h / .cpp is saved -- it was a snapshot: a handler added
    //  still showed ✗, and its C++ place opened the old line)
    this.saveSub = vscode.workspace.onDidSaveTextDocument ? vscode.workspace.onDidSaveTextDocument(doc => {
      if (this.disposed || !doc || !doc.uri || doc.uri.scheme !== 'file' || !/\.(html?|h|hpp|cpp|cc|cxx|js)$/i.test(doc.uri.fsPath)) return;
      // (1010 review of 0.396: a save in this page's C++ tree or web root only -- not every .cpp of the golden tree)
      { const r0 = this.d && this.d.r ? this.d.r : {}; const fp = path.resolve(doc.uri.fsPath).toLowerCase(); const under = x => !!x && (fp === path.resolve(x).toLowerCase() || fp.startsWith(path.resolve(x).toLowerCase() + path.sep)); if (!under(r0.portRoot) && !under(r0.webRoot) && !(this.d && this.d.file && fp === path.resolve(this.d.file).toLowerCase())) return; }   // (1010 review of 0.398 D4: the page itself too)
      clearTimeout(this.refreshT);
      this.refreshT = setTimeout(() => this.refresh(), 1500);
    }) : null;
    this.panel.onDidDispose(() => { this.disposed = true; clearTimeout(this.refreshT); try { if (this.saveSub) this.saveSub.dispose(); } catch (e) { /* gone */ } if (d.overview === this) d.overview = null; });
  }

  async refresh() {
    if (this.disposed || !this.d || this.d.disposed) return;
    try {
      const pi = await this.d.info;
      if (!pi || !pi.ir || this.disposed) return;
      const ov = await this.hub.computeOverview(this.d, pi);
      if (!this.disposed) this.set(ov);
    } catch (e) { this.hub.logErr('接線總覽重新整理', e); }
  }

  set(data) {
    this.data = data;
    this.panel.webview.postMessage({ type: 'data', data });
  }

  onMessage(m) {
    switch (m && m.type) {
      case 'ready': this.panel.webview.postMessage({ type: 'data', data: this.data }); break;
      case 'select':
        if (!this.d.disposed) {
          this.d.panel.reveal(this.d.panel.viewColumn, true);
          this.d.post({ type: 'selectId', id: String(m.id || ''), origin: 'overview' });
        }
        break;
      case 'open': {
        // (1009 second review (webviews #5): only a place this overview listed (or its page) -- not whatever path came back)
        const f0 = typeof m.file === 'string' ? m.file : '';
        const listed = !!f0 && ((this.d && this.d.file && web.samePath(this.d.file, f0)) ||
          ((this.data && this.data.rows) || []).some(r => (r.events || []).some(ev => ['port', 'golden'].some(k => ev[k] && ev[k].at && ev[k].at.file && web.samePath(ev[k].at.file, f0)))));
        if (!listed) break;
        this.hub.openTarget({ kind: m.kind === 'golden' ? 'golden' : m.kind === 'port' ? 'port' : 'web', file: f0, line: m.line | 0, col: m.col | 0 }, this.d);
        break;
      }
      default: break;
    }
  }
}

