      const go1 = await vscode.window.showWarningMessage(path.basename(String(prog)) + '（PID ' + left.map(p => p.pid).join('、') + '）' + why1 + '。要強制結束嗎？強制結束時馬達停止、繼電器、存檔都不會處理。', { modal: true }, '強制結束');
      if (go1 !== '強制結束') { this.stopEpoch = (this.stopEpoch || 0) + 1; vscode.window.setStatusBarMessage('$(info) 沒有強制結束 ' + path.basename(String(prog)) + '，這次不建置也不啟動', 8000); return []; }
