      const p = vscode.window.createWebviewPanel(RunStrip.TYPE, '▶ 執行與除錯', { viewColumn: vscode.ViewColumn.Active, preserveFocus: false },
        { enableScripts: true, enableCommandUris: false, retainContextWhenHidden: true, localResourceRoots: this.roots() });
      this.attach(p);
      // (turned off while it was being made: it goes again)
      if (!this.enabled() || this.closedByUser()) { (this.selfGone = this.selfGone || new WeakSet()).add(p); try { p.dispose(); } catch (e) { /* gone */ } if (this.panel === p) this.panel = null; return null; }
      try { await vscode.commands.executeCommand('workbench.action.lockEditorGroup'); } catch (e) { /* an old VS Code */ }
      // (1009 EastSun: pinned -- its tab shows a pin, not an ×, and 關閉其他／全部關閉 leave a pinned tab open)
